# Independent arithmetic and design checks for the paper-linked chart examples.
source("03_learning/examples/paper_linked_tests.R")
rejects <- function(expr) inherits(tryCatch({ force(expr); NULL }, error = identity), "error")
set.seed(2210)
before_seed <- .Random.seed
fixture <- make_paper_fixture()
stopifnot(identical(before_seed, .Random.seed))
b <- run_paper_base_examples(fixture)
p <- b$published

# Published numerical anchors; no expected output is generated by the fitted model.
stopifnot(abs(p$paired$p.value - .001001424) < 1e-9,
          abs(unname(p$chi_square$statistic) - 32) < 1e-10,
          abs(p$mcnemar$p.value - .0338948535) < 1e-9,
          abs(p$mcnemar_exact$p.value - 18/256) < 1e-12,
          abs(p$mcnemar_mid_p - 10/256) < 1e-12,
          abs(p$mcnemar_cc$p.value - .0770998717) < 1e-9,
          abs(p$rank_discrepancy$p.value - .0039767517) < 1e-9,
          abs(p$rank_discrepancy$p.value - .398) > .39)

# Welch statistic, df and CI computed from sample moments, separately from t.test.
d <- fixture$people
x <- d$marker[d$group == "comparison"]
y <- d$marker[d$group == "reference"]
vx <- var(x) / length(x)
vy <- var(y) / length(y)
se <- sqrt(vx + vy)
df <- (vx + vy)^2 / (vx^2 / (length(x)-1) + vy^2 / (length(y)-1))
ci <- mean(x)-mean(y) + c(-1, 1) * qt(.975, df) * se
stopifnot(abs(unname(b$welch$statistic) - (mean(x)-mean(y))/se) < 1e-10,
          max(abs(b$welch$conf.int - ci)) < 1e-10,
          abs(unname(b$paired_t$estimate) - mean(d$after-d$before)) < 1e-10,
          isTRUE(all.equal(unname(b$Z$bh), c(.012, .04, .0933333333333333, .6))),
          isTRUE(all.equal(unname(b$Z$holm), c(.012, .06, .14, .6))))

# The Poisson group-only offset fit equals aggregated events / aggregated exposure.
rates <- tapply(d$episodes, d$group, sum) / tapply(d$person_years, d$group, sum)
stopifnot(abs(exp(coef(b$poisson)["groupcomparison"]) - rates[2]/rates[1]) < 1e-6)

bad <- fixture; bad$people$id[2] <- bad$people$id[1]
stopifnot(rejects(run_paper_base_examples(bad)))
bad <- fixture; bad$people$person_years[1] <- 0
stopifnot(rejects(run_paper_base_examples(bad)))
bad <- fixture; bad$people$marker[1] <- NA_real_
stopifnot(rejects(run_paper_base_examples(bad)))
bad <- fixture; bad$people$event[1] <- 2L
stopifnot(rejects(run_paper_base_examples(bad)))
bad <- fixture; bad$counts[1, 1] <- .5
stopifnot(rejects(run_paper_base_examples(bad)))
bad <- fixture; bad$metadata <- bad$metadata[12:1, , drop = FALSE]
stopifnot(rejects(run_paper_base_examples(bad)))
bad <- fixture; bad$visits[2, c("id", "visit")] <- bad$visits[1, c("id", "visit")]
stopifnot(rejects(run_paper_base_examples(bad)))

args <- commandArgs(trailingOnly = TRUE)
if (length(args) > 1L || (length(args) == 1L && args != "--full")) stop("Use --full or no argument")
if (length(args)) {
  e <- run_paper_extended_examples(fixture)
  stopifnot(e$multinomial$convergence == 0L, e$negative_binomial$converged,
            is.finite(e$negative_binomial$theta), e$negative_binomial$theta > 0,
            !e$mixed_singular, e$gee$geese$error == 0L,
            is.null(e$mixed@optinfo$conv$lme4$messages),
            all(is.finite(coef(e$survey))), all(is.finite(coef(e$cox))),
            all(is.finite(e$cox_ph_check$table)),
            all(is.finite(e$ordinal$beta)),
            is.finite(e$mixed_lrt$`Pr(>Chisq)`[2]),
            all(e$kaplan_meier$surv >= 0 & e$kaplan_meier$surv <= 1),
            nrow(e$deseq2) == 500L, nrow(e$intensity_limma) == 500L)
  # Hand-checkable competing-risk fixture: cause 1 at t=1, cause 2 at t=2,
  # cause 1 at t=3, censor at t=4. Aalen-Johansen CIF1(3)=1/2; 1-KM=5/8.
  cif <- cmprsk::cuminc(c(1, 2, 3, 4), c(1, 2, 1, 0), cencode = 0)
  cif_at_3 <- cmprsk::timepoints(cif, times = 3)$est[1, 1]
  km <- survival::survfit(survival::Surv(c(1, 2, 3, 4), c(1, 0, 1, 0)) ~ 1)
  stopifnot(abs(cif_at_3 - .5) < 1e-12,
            abs(1 - summary(km, times = 3)$surv - .625) < 1e-12)
  for (table in list(e$deseq2, e$edger, e$voom_limma, e$intensity_limma)) {
    adjusted_name <- intersect(c("padj", "FDR", "adj.P.Val"), names(table))
    q <- table[[adjusted_name]]
    stopifnot(length(adjusted_name) == 1L, any(is.finite(q)),
              all(q[is.finite(q)] >= 0 & q[is.finite(q)] <= 1))
  }
  cat("PASS: every extended chart method executed; convergence and independent CIF fixture\n")
}
cat("PASS: published paired/chi-square/McNemar anchors, rank discrepancy, Welch/offset arithmetic and invalid-input rejection\n")
